#!/usr/bin/env python3
"""Compile the actual closed-rim helper with independent geometric controls."""
from pathlib import Path
import subprocess
import tempfile
ROOT=Path(__file__).resolve().parents[2]
HARNESS='import Foundation\nimport CoreGraphics\nstruct ReaderTranslationRegion {let id:String;let rect:CGRect;let source:String}\nstruct ReaderTranslationBalloonInterior {let rect:CGRect;let center:CGPoint;let spans:[Double];let contourVerified:Bool}\nvar budget=4_000_000\nfunc control(_ kind:Int)->CGImage{\n let c=CGContext(data:nil,width:280,height:280,bitsPerComponent:8,bytesPerRow:1120,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.premultipliedLast.rawValue)!\n c.setFillColor(gray:0.3,alpha:1);c.fill(CGRect(x:0,y:0,width:280,height:280));c.setStrokeColor(gray:1,alpha:1);c.setLineWidth(4)\n if kind==0 || kind==1 {c.strokeEllipse(in:CGRect(x:35,y:25,width:210,height:230))}\n if kind==1{c.setFillColor(gray:0.3,alpha:1);c.fill(CGRect(x:130,y:20,width:20,height:20))}\n if kind==2{for y in stride(from:90,to:190,by:20){c.strokeEllipse(in:CGRect(x:105,y:y,width:25,height:15))}}\n if kind==3{c.setFillColor(gray:1,alpha:1);c.fill(CGRect(x:0,y:0,width:280,height:280))}\n return c.makeImage()!\n}\nfor kind in 0...3{\n let r=ReaderTranslationWhiteRimBalloon.inspect(image:control(kind),owned:[CGRect(x:100,y:80,width:70,height:120)],padding:85,pixelBudget:&budget)\n precondition((r != nil)==(kind==0),"control failed \\(kind)");print("white-rim-control",kind,r != nil)\n}\n\n\nvar tinyBudget=1\nprecondition(ReaderTranslationWhiteRimBalloon.inspect(image:control(0),owned:[CGRect(x:100,y:80,width:70,height:120)],padding:85,pixelBudget:&tinyBudget)==nil)\nlet invalid=CGRect(x:CGFloat.infinity,y:0,width:10,height:10)\nprecondition(ReaderTranslationWhiteRimBalloon.inspect(image:control(0),owned:[invalid],padding:85,pixelBudget:&budget)==nil)\nprint("WHITE_RIM_CONTOUR six controls passed")\n'
with tempfile.TemporaryDirectory(prefix="aidoku-white-rim-test-") as d:
    p=Path(d); (p/"main.swift").write_text(HARNESS)
    subprocess.run(["swiftc","-O",str(ROOT/"Aidoku/Core/Translation/ReaderTranslationWhiteRimBalloon.swift"),str(p/"main.swift"),"-o",str(p/"test")],check=True)
    subprocess.run([str(p/"test")],check=True)
